import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.DaAXJYxM.js";const m=JSON.parse('{"title":"第24章 食堂","description":"","frontmatter":{},"headers":[],"relativePath":"第24章_食堂.md","filePath":"第24章_食堂.md"}'),r={name:"第24章_食堂.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第24章-食堂" tabindex="-1">第24章 食堂 <a class="header-anchor" href="#第24章-食堂" aria-label="Permalink to &quot;第24章 食堂&quot;">​</a></h1><p>市三中的食堂是两层的。一楼人多，二楼人少一点，但要在十一点四十之前上去，晚了就没位置。</p><p>开学之前我不知道这些。开学第三天我就知道了，因为沈聿告诉我。</p><p>他说，你要是不想排长队，就提前五分钟走。</p><p>我说，提前走不就被抓了。</p><p>他说，那就排长队。</p><p>他说话总是这样，先给方案，再给方案的代价，让人自己选。</p><p>我这个人不太会选，所以我一般就排长队。</p><p>九月的食堂很挤。二楼靠窗有十几张长桌，每张能坐八个人，两边各四个。吃饭的时候一桌的人互相都不认识，各自低头扒饭，偶尔有人跟熟人打个招呼。</p><p>我注意到她在靠窗那边的第三张桌子，坐北边，背对着门口。</p><p>这个位置是我第三天发现的。那天我端着盘子找位置，一抬头看见她的背影。她低着头，吃得很慢。</p><p>我没过去。</p><p>我端着盘子绕了半圈，在南边找了张桌子坐下。</p><p>坐下之后我发现一件事：从我这个位置往上看，正好能看到她的肩膀。她吃得很慢，小口小口，筷子夹起来要停一下。</p><p>那天我吃完了没走，坐在那儿又坐了十分钟。宿舍的饭卡每天扣两次，早一次晚一次，超时不走也不会有人赶。</p><p>过了三天，她发消息说：你是不是在看我。</p><p>我说，没有。</p><p>她说，我看你那个方向好几天了。</p><p>我说，你怎么知道我看你。</p><p>她说，我感觉到的。</p><p>那天晚上她说了第二句。</p><p>她说，你要不要坐过来。</p><p>我说，行吗。</p><p>她说，试试。</p><p>第二天中午，我提前五分钟走，端着盘子上了二楼。她已经在那边了，坐的还是那个位置。她看见我，往里面挪了挪。</p><p>我坐下了。</p><p>一桌八个人，我们中间隔着一张桌面的距离，右边是个男生，左边是个女生。我坐下来的时候那两个人都没看我，各吃各的。</p><p>我跟她说了一句。</p><p>我说，我先动筷子了。</p><p>她说，嗯。</p><p>然后我们就再没说话。</p><p>那顿饭吃了二十分钟。我们两个人都低着头，吃饭的声音听起来比平时大。我能闻到她身上的味道，不是香味，是校服洗衣粉的味道，很淡。</p><p>吃到一半，有人走过来了。</p><p>是个女生，坐在她旁边的位置。那个女生把盘子放下，问她：这是谁啊。</p><p>她抬了一下头。</p><p>她说，同学。</p><p>那个女生看了我一眼，说，哪的。</p><p>她说，三楼那个重点班的。</p><p>那个女生哦了一声，说，这么远。</p><p>她说，他正好没位置。</p><p>那个女生没再问，低头吃饭。</p><p>那顿饭的后半段我们都没说话。吃完她把盘子端起来先走了，走的时候没有看我。</p><p>那天下午她给我发消息。</p><p>她说，以后不一起吃了。</p><p>我问，为什么。</p><p>她说，你看到了。</p><p>我说，我们就坐着吃饭。</p><p>她说，坐着吃饭也能被看见。</p><p>她说，我那个同学回去会说的。</p><p>我问，说什么。</p><p>她说，说我认识一个重点班的。</p><p>我那时候不太明白这句话有什么问题。一个重点班的同学，说起来也不是什么坏事。</p><p>第二天我才明白。</p><p>那天中午我没上二楼，在一楼吃的。吃到一半，我听见旁边桌有人在说二楼的事，说有个女生跟楼上重点班的谁认识。说话的语气很随意，像在说一件小事。</p><p>我抬了一下头。</p><p>说话的人我不知道是谁，可我知道我们在同一个学校里，一共就两千多人。</p><p>在这个学校里，一件事传开的速度，比从三楼走到二楼还快。</p><p>那天晚上我跟她说，我知道了。</p><p>她说，你知道什么了。</p><p>我说，为什么不能一起吃饭。</p><p>她说，嗯。</p><p>她说，你别怪他们，他们没恶意。</p><p>我说，我没怪。</p><p>她说，你这个人就是这样，什么都说没怪。</p><p>我说，那我怪谁。</p><p>她说，怪我。</p><p>我没有回。</p><p>隔了一会儿，她说：其实我挺喜欢跟你吃饭的。</p><p>她说，就是吃不了。</p><p>那天之后我们就再没在食堂坐在一起过。我们各吃各的，她坐北边，我坐南边，隔着几张桌子。有时候我抬头看她的方向，她已经吃完了，端着盘子往外走。</p><p>后来我就习惯了一个人吃饭。</p><p>有时候沈聿会跟我一起。他吃饭很快，五分钟能吃完一碗，吃完就坐着等我，边等边拿手机看题。</p><p>有一次他问我，你怎么老看那边。</p><p>我说，那边窗子亮。</p><p>他说，那天我看见一个女生在看你。</p><p>我说，哪有人看我。</p><p>他说，真的，就坐那边第三张桌的。</p><p>我没接话。</p><p>他说，你脸红什么。</p><p>我说，热的。</p><p>他说，都快十一月了。</p><p>从远处看她跟同学在一起的时候，是另一个样子。</p><p>她会笑，笑得比跟我在一起的时候多。她会跟人说话，会伸手去拍别人的肩膀。有一次她给旁边的人递了一双筷子，动作很自然。</p><p>我那时候才知道，她在学校是有人跟她说话的。</p><p>她不是那种孤零零的人。她跟我说过她没什么朋友，那是假的。</p><p>我那时候不明白她为什么要说假话。后来我懂了：她跟那些人的关系，和跟我的关系，是两种不同的东西。</p><p>两个东西都需要，但只有一个能拿出去。</p><p>走的时候她不回头。</p><p>我坐在那儿，把最后几口饭扒完，也端着盘子出去。</p><p>两个人从同一个门走出去，中间隔着两三分钟，像两班错开的车。</p><p>那年秋天，我们在食堂碰见过几次，每次都是她端着盘子往外走，我端着盘子往里进。</p><p>有一次我们擦肩。她没说话，我也没说话。</p><p>走到她身后的时候，我听到她轻轻说了一句。</p><p>她说：今天的汤不要喝。</p><p>我端着盘子，没回头。</p><p>那天的汤我确实没喝。后来听说那个汤有问题，晚上有十几个人闹肚子。</p><p>我不知道她是怎么知道的。我也没问。</p><p>那是我第一次觉得，在一个学校里，她比我懂得多得多。</p>',98)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
